ALTER TABLE public.tg_users ADD COLUMN IF NOT EXISTS mining_rate_daily numeric NOT NULL DEFAULT 0.1, ADD COLUMN IF NOT EXISTS mining_pending numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS mining_settled_at timestamptz, ADD COLUMN IF NOT EXISTS wallet_verified boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS wallet_nonce text;
CREATE TABLE public.market_snapshots (id text PRIMARY KEY, data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.market_snapshots TO service_role;
ALTER TABLE public.market_snapshots ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.orange_mining_claim(p_user_id bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE u public.tg_users; elapsed numeric; reward numeric; ts timestamptz := now(); BEGIN SELECT * INTO u FROM public.tg_users WHERE id=p_user_id FOR UPDATE; IF u.mining_started_at IS NULL THEN RAISE EXCEPTION 'Not mining'; END IF; IF ts < u.mining_started_at + interval '2 hours' THEN RAISE EXCEPTION 'Mining not finished'; END IF; elapsed := greatest(0, extract(epoch from (least(ts,u.mining_started_at + interval '2 hours') - coalesce(u.mining_settled_at,u.mining_started_at)))); reward := u.mining_pending + elapsed / 86400 * u.mining_rate_daily; UPDATE public.tg_users SET balance=balance+reward, mining_started_at=ts, mining_settled_at=ts, mining_pending=0 WHERE id=p_user_id; RETURN jsonb_build_object('balance',u.balance+reward,'mining_started_at',ts,'mining_pending',0,'mining_settled_at',ts,'mining_rate_daily',u.mining_rate_daily); END $$;
REVOKE ALL ON FUNCTION public.orange_mining_claim(bigint) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.orange_mining_claim(bigint) TO service_role;
CREATE OR REPLACE FUNCTION public.orange_sync_power(p_user_id bigint, p_level integer, p_rate numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u public.tg_users; ts timestamptz:=now(); elapsed numeric; BEGIN SELECT * INTO u FROM public.tg_users WHERE id=p_user_id FOR UPDATE; IF u.mining_started_at IS NOT NULL THEN elapsed:=greatest(0,extract(epoch from (least(ts,u.mining_started_at+interval '2 hours')-coalesce(u.mining_settled_at,u.mining_started_at)))); UPDATE public.tg_users SET mining_pending=mining_pending+elapsed/86400*mining_rate_daily, mining_settled_at=ts, power_level=p_level, mining_rate_daily=p_rate WHERE id=p_user_id; ELSE UPDATE public.tg_users SET power_level=p_level,mining_rate_daily=p_rate WHERE id=p_user_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.orange_sync_power(bigint,integer,numeric) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.orange_sync_power(bigint,integer,numeric) TO service_role;